Our data science team spun up a scratch environment for model experiments. It's our dev account, nobody outside the team uses it. CDK in JavaScript. Quick look before I run deploy?

```js
const { Instance, InstanceType, Peer, Port, MachineImage } = require('aws-cdk-lib/aws-ec2');
const { DatabaseCluster } = require('aws-cdk-lib/aws-docdb');
const { LogGroup, RetentionDays } = require('aws-cdk-lib/aws-logs');

// dev only - we'll lock this down before anything goes near prod
const notebook = new Instance(this, 'NotebookHost', {
  vpc,
  instanceType: new InstanceType('m5.xlarge'),
  machineImage: MachineImage.latestAmazonLinux2023(),
});
notebook.connections.allowFrom(Peer.anyIpv4(), Port.tcp(22));

// single node, wiped when the stack is deleted, no backups configured
const store = new DatabaseCluster(this, 'ExperimentStore', {
  vpc,
  masterUser: { username: 'admin' },
  instances: 1,
  instanceType: new InstanceType('r5.large'),
});
store.connections.allowFrom(Peer.anyIpv4(), Port.tcp(27017));

new LogGroup(this, 'NotebookLogs', {
  retention: RetentionDays.ONE_WEEK,
});
```
